<script setup>
import { computed, ref } from 'vue'
const props = defineProps({ organizations: { type:Array, default:() => [] }, applications: { type:Array, default:() => [] }, loading:Boolean })
const emit = defineEmits(['apply','refresh'])
const activeTab = ref('organizations')
const safeOrganizations = computed(() => Array.isArray(props.organizations) ? props.organizations : [])
const safeApplications = computed(() => Array.isArray(props.applications) ? props.applications : [])
const applicationByOrganization = computed(() => new Map(safeApplications.value.map((item) => [item.organization_id,item])))
function applicationLabel(id) { const status=applicationByOrganization.value.get(id)?.status; return ({pending:'审核中',approved:'已批准',rejected:'已拒绝，可重新申请'})[status] || '申请加入' }
function canApply(id) { const status=applicationByOrganization.value.get(id)?.status; return !props.loading && status !== 'pending' && status !== 'approved' }
</script>

<template>
  <section class="page-stack"><article class="panel"><div class="application-toolbar"><div class="application-tabs" role="tablist"><button :class="{active:activeTab === 'organizations'}" type="button" @click="activeTab='organizations'">可申请组织 <span>{{ safeOrganizations.length }}</span></button><button :class="{active:activeTab === 'applications'}" type="button" @click="activeTab='applications'">我的申请 <span>{{ safeApplications.length }}</span></button></div><button class="text-button" type="button" @click="emit('refresh')">刷新</button></div><div v-if="activeTab === 'organizations'" class="tab-panel"><ul class="item-list"><li v-for="organization in safeOrganizations" :key="organization.ID"><div><strong>{{ organization.name }}</strong><small>{{ organization.code }} · {{ organization.parent_id ? '下级组织' : '一级组织' }}</small></div><button type="button" :disabled="!canApply(organization.ID)" @click="emit('apply', organization.ID)">{{ applicationLabel(organization.ID) }}</button></li><li v-if="!safeOrganizations.length" class="muted">当前没有可申请的公开组织。</li></ul></div><div v-else class="tab-panel"><ul class="item-list"><li v-for="application in safeApplications" :key="application.id"><div><strong>{{ application.organization_name }}</strong><small>提交于 {{ new Date(application.created_at).toLocaleString() }}</small></div><span :class="['status',application.status]">{{ ({pending:'审核中',approved:'已批准',rejected:'已拒绝'})[application.status] || application.status }}</span></li><li v-if="!safeApplications.length" class="muted">还没有提交组织申请。</li></ul></div></article></section>
</template>

<style scoped>
