0!important;text-align:center}@media(max-width:600px){.panel{padding:20px}.application-toolbar{align-items:stretch;flex-direction:column}.application-toolbar>.text-button{align-self:flex-end}.application-tabs{width:100%}.application-tabs button{flex:1;justify-content:center}.item-list li{align-items:flex-start;flex-wrap:wrap}.item-list button,.status{margin-left:auto}}
</style>
